const body = $input.first().json.body || $input.first().json;
const data = body.data || body;

const remoteJid = data.key?.remoteJid || data.remoteJid || '';
const fromMe = data.key?.fromMe || false;
const messageType = data.messageType || 'conversation';
const pushName = data.pushName || 'Cliente';

let textMessage = '';
if (data.message?.conversation) {
  textMessage = data.message.conversation;
} else if (data.message?.extendedTextMessage?.text) {
  textMessage = data.message.extendedTextMessage.text;
} else if (data.message?.buttonsResponseMessage?.selectedDisplayText) {
  textMessage = data.message.buttonsResponseMessage.selectedDisplayText;
}

return [{
  json: {
    remoteJid,
    fromMe,
    messageType,
    pushName,
    textMessage: textMessage.trim().toLowerCase(),
    originalText: textMessage.trim(),
    timestamp: new Date().toISOString()
  }
}];

